union Residual<T> {
    case Present(value: T)
    case Absent
}
func Consume(value: System.Void) -> int => 42
func Main() -> int {
    let residual: System.Void = ()
    let wrapped: Residual<System.Void> = Residual<System.Void>.Present(residual)
    return match wrapped {
        .Present(let value) => Consume(value)
        .Absent => 1
        _ => 2
    }
}
